description:
Implement a `useEventListener` hook that attaches an event listener to a target element (defaulting to `window`) and removes it on unmount. The handler should always reflect the latest function reference without re-subscribing.

**Example:**
```tsx
useEventListener('keydown', (e) => console.log(e.key));
useEventListener('click', handler, buttonRef);
```

starter_code:
import { useEffect, useRef } from 'react';

export function useEventListener(
  eventName: string,
  handler: (event: Event) => void,
  element?: React.RefObject<Element> | null
): void {
  // your code here
}

test_suite:
test('handler fires when event is dispatched on window', () => {
  const handler = vi.fn();
  renderHook(() => useEventListener('click', handler));
  act(() => window.dispatchEvent(new MouseEvent('click')));
  expect(handler).toHaveBeenCalledTimes(1);
});

test('listener is removed on unmount', () => {
  const handler = vi.fn();
  const { unmount } = renderHook(() => useEventListener('click', handler));
  unmount();
  act(() => window.dispatchEvent(new MouseEvent('click')));
  expect(handler).not.toHaveBeenCalled();
});

test('uses latest handler without re-subscribing', () => {
  let calls = 0;
  const h1 = () => { calls += 1; };
  const h2 = () => { calls += 10; };
  const { rerender } = renderHook(({ h }) => useEventListener('click', h), { initialProps: { h: h1 } });
  rerender({ h: h2 });
  act(() => window.dispatchEvent(new MouseEvent('click')));
  expect(calls).toBe(10);
});

// __hidden__
test('attaches to ref element when provided', () => {
  const div = document.createElement('div');
  const ref = { current: div };
  const handler = vi.fn();
  renderHook(() => useEventListener('click', handler, ref));
  act(() => div.dispatchEvent(new MouseEvent('click', { bubbles: false })));
  expect(handler).toHaveBeenCalledTimes(1);
});

solution:
import { useEffect, useRef } from 'react';

export function useEventListener(
  eventName: string,
  handler: (event: Event) => void,
  element?: React.RefObject<Element> | null
): void {
  const savedHandler = useRef(handler);
  useEffect(() => { savedHandler.current = handler; });

  useEffect(() => {
    const target = element?.current ?? window;
    if (!target?.addEventListener) return;
    const listener = (event: Event) => savedHandler.current(event);
    target.addEventListener(eventName, listener);
    return () => target.removeEventListener(eventName, listener);
  }, [eventName, element]);
}
